 print(r.pages[i].extract_text(extraction_mode='layout'))
links=[]
for i,p in enumerate(r.pages):
 for a in p.get('/Annots',[]):
  a=a.get_object();action=a.get('/A',{});u=action.get('/URI')
  if u:links.append((i+1,str(u)))
print('Artifact links:',[(p,u) for p,u in links if any(w in u.lower() for w in ['github','gitlab','code','zenodo','osf'])])
